// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Combined state and data for an item in a metadata collection.
 *
 * This enum provides type-safe representation of item state with associated data.
 * Data presence is encoded in the variant itself, eliminating the need for
 * separate `state` and `data` fields.
 */

public enum PostItemState: Equatable, Hashable {
    
    /**
     * No cached data available, needs fetch
     */
    case missing
    /**
     * Fetch in progress, no cached data to show
     */
    case fetching
    /**
     * Fetch in progress, showing cached data while loading
     */
    case fetchingWithData(data: FullEntityAnyPostWithEditContext
    )
    /**
     * Fresh data, no fetch needed
     */
    case fresh(data: FullEntityAnyPostWithEditContext
    )
    /**
     * Cached data is outdated, could benefit from refresh
     */
    case stale(data: FullEntityAnyPostWithEditContext
    )
    /**
     * Fetch failed, no cached data available
     */
    case failed(error: String
    )
    /**
     * Fetch failed, showing last known cached data
     */
    case failedWithData(error: String, data: FullEntityAnyPostWithEditContext
    )





}

#if compiler(>=6)
extension PostItemState: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePostItemState: FfiConverterRustBuffer {
    typealias SwiftType = PostItemState

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PostItemState {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .missing
        
        case 2: return .fetching
        
        case 3: return .fetchingWithData(data: try FfiConverterTypeFullEntityAnyPostWithEditContext.read(from: &buf)
        )
        
        case 4: return .fresh(data: try FfiConverterTypeFullEntityAnyPostWithEditContext.read(from: &buf)
        )
        
        case 5: return .stale(data: try FfiConverterTypeFullEntityAnyPostWithEditContext.read(from: &buf)
        )
        
        case 6: return .failed(error: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .failedWithData(error: try FfiConverterString.read(from: &buf), data: try FfiConverterTypeFullEntityAnyPostWithEditContext.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PostItemState, into buf: inout [UInt8]) {
        switch value {
        
        
        case .missing:
            writeInt(&buf, Int32(1))
        
        
        case .fetching:
            writeInt(&buf, Int32(2))
        
        
        case let .fetchingWithData(data):
            writeInt(&buf, Int32(3))
            FfiConverterTypeFullEntityAnyPostWithEditContext.write(data, into: &buf)
            
        
        case let .fresh(data):
            writeInt(&buf, Int32(4))
            FfiConverterTypeFullEntityAnyPostWithEditContext.write(data, into: &buf)
            
        
        case let .stale(data):
            writeInt(&buf, Int32(5))
            FfiConverterTypeFullEntityAnyPostWithEditContext.write(data, into: &buf)
            
        
        case let .failed(error):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(error, into: &buf)
            
        
        case let .failedWithData(error,data):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(error, into: &buf)
            FfiConverterTypeFullEntityAnyPostWithEditContext.write(data, into: &buf)
            
        }
    }
}


